using namespace risc0;
namespace rk = risc0::circuit::rv32im_v2;

static_assert(EF_NPM == EF_NPC + rk::RK_QN + rk::RK_HN, "poly_mix table size");

__constant__ uint32_t ef_qtab[4];

// One thread: poly_mix table (powers, products, hoisted out/mix terms) and the
// 4-entry vanishing quotient table 1/((3*rou^c)^(2^po2) - 1), c = cycle & 3.
__global__ void ef_prep(const FpExt* pm_in, const Fp* out, const Fp* mix, FpExt* tab, uint32_t* qtab,
                        Fp rou, uint32_t po2, const Fp* data, const Fp* accum) {
  if (threadIdx.x != 0 || blockIdx.x != 0) return;
  ef_ptrs[0] = reinterpret_cast<uint64_t>(data);
  ef_ptrs[1] = reinterpret_cast<uint64_t>(accum);
  ef_ptrs[2] = reinterpret_cast<uint64_t>(mix);
  ef_ptrs[3] = reinterpret_cast<uint64_t>(out);
  for (uint32_t i = 0; i < EF_NPC; i++) tab[i] = pm_in[i];
  for (uint32_t i = 0; i < rk::RK_QN; i++) tab[EF_NPC + i] = pm_in[rk::rk_qa[i]] * pm_in[rk::rk_qb[i]];
  rk::rk_hoist(tab, out, mix, tab + EF_NPC + rk::RK_QN);
  for (uint32_t c = 0; c < 4; c++) {
    Fp x = Fp(3) * pow(rou, c);
    Fp y = pow(x, size_t(1) << po2);
    qtab[c] = inv(y - Fp(1)).asRaw();
  }
}

__global__ void ef_prep_n(const FpExt* tab, FpExt* tabn) {
  uint32_t i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= EF_NPM) return;
  tabn[i] = FpExt(tab[i].elems[1] * Fp(Fp::P - 11), tab[i].elems[2] * Fp(Fp::P - 11), tab[i].elems[3] * Fp(Fp::P - 11), Fp(0));
}

// wmma_hip.py: the WMMA A operands (gfx12 chains): Q[k][n] for n = (j = pd[n / 4], b = n % 4), byte a =
// byte b of (pm_raw[k][j] * 256^a mod P); pd = {0, 2, 1, 3} is the wave64 D row-group order.
__global__ void ef_prep_q(const FpExt* tab) {
  const uint32_t i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= EF_NPM * 16u) return;
  const uint32_t k = i / 16u, n = i % 16u, j = (0x3120u >> (4u * (n / 4u))) & 15u, b = n % 4u;
  const uint64_t x = tab[k].elems[j].asRaw();
  uint32_t dw = 0;
  for (uint32_t a = 0; a < 4; a++) dw |= uint32_t((((x << (8u * a)) % Fp::P) >> (8u * b)) & 255u) << (8u * a);
  ef_wq_raw[i] = dw;
}

// Phase-split variant: even blocks evaluate the main chain (poly_fp), odd blocks the LogUp chain
// (rk_accblk) of the same 128 rows; ef_combine adds the two partials and scales by the quotient.
static_assert(EF_SPLIT_SHIFT == 1, "ef_eval_split has two phases: main (even blocks) and LogUp (odd)");
__launch_bounds__(EF_THREADS, EF_MINB_K)
__global__ void ef_eval_split(Fp* check, Fp* data, Fp* accum, Fp* mix, Fp* out, uint32_t domain, Fp* scratch) {
  FpExt* pm = nullptr;
  const uint32_t rb = blockIdx.x >> EF_SPLIT_SHIFT, ph = blockIdx.x & ((1u << EF_SPLIT_SHIFT) - 1u);
  uint32_t cycle = blockDim.x * rb + threadIdx.x;
#ifdef EF_WM
  // The WMMA chains need whole waves: a partial wave (domains below 64 rows only) evaluates
  // wrapped rows and skips their stores.
  const bool ef_live = cycle < domain;
  if (domain == 0 || (!ef_live && (domain & 63u) == 0)) return;
  if (!ef_live) cycle &= domain - 1u;
#else
  const bool ef_live = true;
  if (cycle >= domain) return;
#endif
  uint32_t lslab[RK_NWORDS];
  Fp* slab = reinterpret_cast<Fp*>(lslab);
  Fp* args[5] = {accum, data, out, mix, slab};
  FpExt t;
  Fp* dst;
  if (ph == 0) { t = rk::poly_fp(cycle, domain, args); dst = check; }
  else { t = rk::rk_accblk(cycle, domain, reinterpret_cast<Fp*>(args[4])); dst = scratch; }
  if (ef_live)
    for (uint32_t i = 0; i < 4; i++) dst[i * domain + cycle] = t.elems[i];
}
__global__ void ef_combine(Fp* check, const Fp* scratch, uint32_t domain) {
  uint32_t cycle = blockDim.x * blockIdx.x + threadIdx.x;
  if (cycle >= domain) return;
  Fp quot = Fp::fromRaw(ef_qtab[cycle & 3]);
  for (uint32_t i = 0; i < 4; i++) check[i * domain + cycle] = (check[i * domain + cycle] + scratch[i * domain + cycle]) * quot;
}
#include "cuda.h"
#include "device_alloc.h"
#ifdef __HIPCC__
// hipMemcpyToSymbol is unreliable without -fgpu-rdc: copy to the symbol's address.
#define EF_COPY_SYM(sym, src, n)                                                  \
  do {                                                                            \
    void* p_ = nullptr;                                                           \
    CUDA_OK(hipGetSymbolAddress(&p_, HIP_SYMBOL(sym)));                           \
    CUDA_OK(hipMemcpyAsync(p_, (src), (n), hipMemcpyDeviceToDevice, stream));     \
  } while (0)
#else
#define EF_COPY_SYM(sym, src, n)                                                  \
  CUDA_OK(cudaMemcpyToSymbolAsync(sym, (src), (n), 0, cudaMemcpyDeviceToDevice, stream))
#endif
static cudaStream_t getEvalCheckStream() {
  int dev = getCachedDevice();
  static cudaStream_t streams[16] = {};
  if (!streams[dev]) CUDA_OK(cudaStreamCreateWithFlags(&streams[dev], cudaStreamNonBlocking));
  return streams[dev];
}
static cudaEvent_t getEvalCheckEvent() {
  int dev = getCachedDevice();
  static cudaEvent_t events[16] = {};
  if (!events[dev]) CUDA_OK(cudaEventCreateWithFlags(&events[dev], cudaEventDisableTiming));
  return events[dev];
}
// scratch: per-device LogUp partials of the split kernel (4 Fp per row), offset
// by a 4 KB pad (EF_SCRATCH_PAD) to avoid the DRAM/L2 aliasing with `check`
// seen in the harness at po2=21.
struct EfBufs {
  FpExt* pm = nullptr; FpExt* tab = nullptr; uint32_t* q = nullptr; FpExt* tabn = nullptr;
  char* scratch_base = nullptr; Fp* scratch = nullptr; uint32_t scratch_n = 0;
};
static EfBufs& efBufs() {
  int dev = getCachedDevice();
  static EfBufs bufs[16];
  if (!bufs[dev].pm) {
    CUDA_OK(cudaMalloc(&bufs[dev].pm, EF_NPC * sizeof(FpExt)));
    CUDA_OK(cudaMalloc(&bufs[dev].tab, EF_NPM * sizeof(FpExt)));
    CUDA_OK(cudaMalloc(&bufs[dev].q, 4 * sizeof(uint32_t)));
    CUDA_OK(cudaMalloc(&bufs[dev].tabn, EF_NPM * sizeof(FpExt)));
    CUDA_OK(cudaFuncSetCacheConfig((const void*)ef_eval_split, cudaFuncCachePreferL1));
  }
  return bufs[dev];
}

extern "C" {
const char* risc0_circuit_rv32im_cuda_eval_check(Fp* check, const Fp* ctrl, const Fp* data,
                                                 const Fp* accum, const Fp* mix, const Fp* out,
                                                 const Fp& rou, uint32_t po2, uint32_t domain,
                                                 const FpExt* poly_mix_pows) {
  try {
    cudaStream_t stream = getEvalCheckStream();
    {
      cudaEvent_t event = getEvalCheckEvent();
      CUDA_OK(cudaEventRecord(event, getPersistentStream()));
      CUDA_OK(cudaStreamWaitEvent(stream, event, 0));
    }
    EfBufs& b = efBufs();
    // Pageable source: cudaMemcpyAsync stages it before returning; the static
    // copy keeps it valid regardless (as the original kernel's staging did).
    static FpExt staging[EF_NPC];
    memcpy(staging, poly_mix_pows, sizeof(staging));
    CUDA_OK(cudaGetLastError());
    CUDA_OK(cudaMemcpyAsync(b.pm, staging, sizeof(staging), cudaMemcpyHostToDevice, stream));
    ef_prep<<<1, 1, 0, stream>>>(b.pm, out, mix, b.tab, b.q, rou, po2, data, accum);
    CUDA_OK(cudaGetLastError());
    EF_COPY_SYM(ef_qtab, b.q, 4 * sizeof(uint32_t));
    EF_COPY_SYM(ef_pm_raw, b.tab, EF_NPM * sizeof(FpExt));
    ef_prep_n<<<(EF_NPM + 127) / 128, 128, 0, stream>>>(b.tab, b.tabn);
    CUDA_OK(cudaGetLastError());
    EF_COPY_SYM(ef_pmn_raw, b.tabn, EF_NPM * sizeof(FpExt));
    ef_prep_q<<<(EF_NPM * 16 + 127) / 128, 128, 0, stream>>>(b.tab);
    CUDA_OK(cudaGetLastError());
    const uint32_t block = EF_THREADS;
    const uint32_t grid = (domain + block - 1) / block;
    if (b.scratch_n < domain) {
      constexpr size_t EF_SCRATCH_PAD = 4096;
      if (b.scratch_base) CUDA_OK(cudaFree(b.scratch_base));  // synchronizes the device
      // Reset first: a failed allocation must not leave a dangling buffer that a later, smaller
      // domain would reuse.
      b.scratch_base = nullptr;
      b.scratch = nullptr;
      b.scratch_n = 0;
      CUDA_OK(risc0_cuda_malloc(&b.scratch_base, 4ull * domain * sizeof(Fp) + EF_SCRATCH_PAD));
      b.scratch = reinterpret_cast<Fp*>(b.scratch_base + EF_SCRATCH_PAD);
      b.scratch_n = domain;
    }
    Fp* s_scratch = b.scratch;
    ef_eval_split<<<grid << EF_SPLIT_SHIFT, block, 0, stream>>>(check, const_cast<Fp*>(data), const_cast<Fp*>(accum),
                                              const_cast<Fp*>(mix), const_cast<Fp*>(out), domain, s_scratch);
    ef_combine<<<grid, block, 0, stream>>>(check, s_scratch, domain);
    CUDA_OK(cudaGetLastError());
    static int s_force_sync = -1, s_skip_sync = -1;
    if (s_force_sync < 0) {
      s_force_sync = std::getenv("RISC0_EVAL_CHECK_FORCE_SYNC") ? 1 : 0;
      s_skip_sync = std::getenv("RISC0_EVAL_CHECK_SKIP_SYNC") ? 1 : 0;
    }
    bool needs_sync;
    if (s_force_sync) needs_sync = true;
    else if (s_skip_sync) needs_sync = false;
    else {
#ifdef __HIPCC__
      // As in eval_check_combined.cu: overlapping eval_check with the next segment is unsafe
      // on RDNA3 and, on a 16 GB card, slower for the memory it holds.
      needs_sync = true;
#else
      static int s_cc_major = -1;
      if (s_cc_major < 0) cudaDeviceGetAttribute(&s_cc_major, cudaDevAttrComputeCapabilityMajor, getCachedDevice());
      needs_sync = s_cc_major >= 12;
#endif
    }
    if (needs_sync) CUDA_OK(cudaStreamSynchronize(stream));
  } catch (const std::exception& err) {
    return strdup(err.what());
  } catch (...) {
    return strdup("Generic exception");
  }
  return nullptr;
}

const char* risc0_circuit_rv32im_cuda_eval_check_dep() {
  try {
    cudaEvent_t event = getEvalCheckEvent();
    CUDA_OK(cudaEventRecord(event, getEvalCheckStream()));
    CUDA_OK(cudaStreamWaitEvent(getPersistentStream(), event, 0));
    CUDA_OK(cudaStreamSynchronize(getEvalCheckStream()));
  } catch (const std::exception& err) {
    return strdup(err.what());
  } catch (...) {
    return strdup("Generic exception");
  }
  return nullptr;
}

const char* risc0_circuit_rv32im_cuda_warmup_eval_check() {
  try {
    cudaStream_t stream = getEvalCheckStream();
    ef_eval_split<<<1, 1, 0, stream>>>(nullptr, nullptr, nullptr, nullptr, nullptr, 0, nullptr);
    CUDA_OK(cudaStreamSynchronize(stream));
  } catch (const std::exception& err) {
    return strdup(err.what());
  } catch (...) {
    return strdup("Generic exception");
  }
  return nullptr;
}
} // extern "C"
